import React, { useState } from 'react'
import { View, Text, TouchableOpacity, Dimensions, ActivityIndicator } from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';


export function Alert() {
    const { selectedNumber, setSelectedNumber, alertActive, setAlertActive, shoppingCartItem } = useContexState();

    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(Number(selectedNumber));

    function Message() {
        return <Text style={styles.listText}>{shoppingCartItem[index] ? 'O número já esta no carrinho!' : 'O número já foi comprado!'}</Text>
    }

    return (alertActive ? <>
        <TouchableOpacity onPress={() => {
            setAlertActive(false);
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />


        <View style={styles.container} >


        </View>
    </> : null
    );
};
